def trace(self, frame, event, arg):
    counts['trace_events'] += 1
    counts['event_' + event] += 1
    counts['filename_checks'] += 1
    names = {'_s2uc_continuation_adapter.py', '_s2uc_pair_context_adapter.py', '_s2uc_factor_hint.py', '_s2uc_perception_recency.py', '_s2uc_four_arm.py', '_s2uc_provisional_hint.py', '_s2ub_candidate_confirmation.py'}
    if Path(frame.f_code.co_filename).name not in names:
        return None
    seen = set()
    frames = set()
    outputs = []

    def visit(x):
        counts['visit_attempts'] += 1
        if id(x) in seen:
            return
        seen.add(id(x))
        counts['unique_object_visits'] += 1
        if type(x) is float:
            counts['unique_float_visits'] += 1
        if type(x) is PerceptionSample:
            counts['sample_visits'] += 1
            counts['sample_float_identity_sum'] += len({id(v) for v in x.values if type(v) is float})
            counts['sample_value_slots'] += len(x.values)
        if isinstance(x, Frame):
            frames.add(id(x))
        if scalar_frame_leaf(x):
            counts['frame_leaf_hits'] += 1
            return
        if isinstance(x, ContinuationAdapter):
            if x.pending_prediction is not None:
                outputs.append(x.pending_prediction)
            visit(vars(x))
        elif isinstance(x, FactorRecencyArm):
            visit(vars(x))
        elif isinstance(x, dict):
            for v in x.values():
                visit(v)
        elif isinstance(x, (list, tuple)):
            for v in x:
                visit(v)
        elif dataclasses.is_dataclass(x) and (not isinstance(x, type)):
            for f in dataclasses.fields(x):
                visit(getattr(x, f.name))
    cursor = frame
    while cursor:
        counts['stack_frames_checked'] += 1
        counts['filename_checks'] += 1
        if Path(cursor.f_code.co_filename).name in names:
            for x in cursor.f_locals.values():
                visit(x)
        cursor = cursor.f_back
    slots = max((1 + (p.context_values is not None) for p in outputs), default=0)
    bytecost = max((sys.getsizeof(p) + sys.getsizeof(p.provenance_json) + sum((sys.getsizeof(v) + sum((sys.getsizeof(x) for x in v)) for v in (p.context_values, p.persistence_values) if v is not None)) for p in outputs), default=0)
    self.frame_peak = max(self.frame_peak, len(frames))
    self.output_slots_peak = max(self.output_slots_peak, slots)
    self.combined_peak = max(self.combined_peak, len(frames) + slots)
    self.output_python_bytes_peak = max(self.output_python_bytes_peak, bytecost)
    self.samples += 1
    assert len(frames) <= 18 and slots <= 2 and (len(frames) + slots <= 20)
    return self.trace
